"""One-time adapt root scene scaffold to canonical Shah2001 operations; private only."""
from pathlib import Path
import re
p=Path(__file__).with_name('shah2001-protocol.mjs');s=p.read_text(encoding='utf8')
def fn(name,new):
 global s
 pat=r'^function '+re.escape(name)+r'\([^\n]*\n?'
 if name=='cell':raise ValueError('Do not edit multiline cell here')
 s,n=re.subn(pat,lambda m:new+'\n',s,flags=re.M);assert n==1,(name,n)
s=s.replace("function conditions(o){", "function conditions(o){")
fn('conditions',r'''function conditions(o,keys=null,x=476,y=125){const labels={precursor_concentration:'Precursor',precursor_mass:'Precursor mass',initial_pressure:'Fill pressure',initial_temperature:'Fill temperature',co2_fill_volume:'CO₂ fill',cell_working_volume:'Cell working volume',pressure:'Reaction pressure',temperature:'Reaction temperature',duration:'Hold duration',accelerating_voltage:'Electron acceleration',instrument_point_resolution:'Instrument resolution'};let rows=[];for(const [k,v]of Object.entries(o.parameters||{})){if(keys&&!keys.includes(k))continue;const q=quantity(v);if(q)rows.push(...wrap((labels[k]||k.replaceAll('_',' '))+': '+q+(v.status==='inferred'?' *':''),26));}return rows.slice(0,10).map((v,i)=>txt(x,y+i*22,v,13)).join('');}''')
fn('loading',r'''function loading(o,r){const id=r.materials.find(m=>m.role==='metal_precursor')?.id;const name=id==='agacac'?'Ag(acac)':id==='ir-precursor'?'Ir precursor':'Printed Pt precursor';return summary(o,cell(170,218,{piston:false})+box(45,76,170,43)+txt(130,103,name,16)+arrow(134,135,90))+note(id==='pt-precursor'?'The Pt ligand name is unresolved as printed; no corrected complex or formula is substituted. Exact mass is unreported.':'Per-experiment masses are not reconstructed from the typical charge range. Cell geometry is illustrative.');}''')
fn('fill',r'''function fill(o,r){const inherited=/^shah-2001-(ir|pt)$/.test(r.record_id);return summary(o,cell(188,222,{fluid:true})+cylinder(54,177,'CO₂')+path('M83 162H107V182')+arrow(111,185))+note(inherited?'* Initial fill conditions are inherited from the common Ag methods, not separately stated for this metal.':'Initial CO₂ fill at 138 bar / 20 °C is distinct from 276 bar reaction conditions; cell working volume is not liquid volume.');}''')
fn('pressurize',r'''function pressurize(o){return summary(o,cell(165,221,{fluid:true,heat:true})+cylinder(320,245,'CO₂')+path('M290 230H250')+arrow(264,229,180)+txt(303,319,'Backside CO₂',14)+txt(105,88,'Heating tape',15))+note('Backside CO₂ controls pressure; heating tape warms the cell and a thermocouple verifies reaction temperature.');}''')
fn('inject',r'''function inject(o,r){const params=o.parameters||{};const ratio=quantity(params.thiol_to_precursor_molar_ratio),thiol=quantity(params.thiol_mass),hydrogen=quantity(params.hydrogen_mass);let art=heading(o.label)+cell(145,231,{fluid:true});for(const [x,y,label]of [[311,125,'Thiol'],[311,238,'H₂']]){art+=`<circle cx="${x}" cy="${y}" r="24" fill="white" stroke="${C.line}" stroke-width="2"/>`;for(let k=0;k<6;k++){const a=k*Math.PI/3;art+=`<circle cx="${x+14*Math.cos(a)}" cy="${y+14*Math.sin(a)}" r="2.7" fill="${C.line}"/>`;}art+=txt(x+73,y+6,label,17);}art+=box(440,82,131,49)+txt(505,102,'High-pressure',14)+txt(505,121,'injection pump',14)+path('M439 105H312V101M311 149V214M287 238H228')+arrow(239,237,180);if(ratio)art+=txt(480,174,'Thiol / precursor',16)+txt(480,202,ratio,17)+txt(480,244,'H₂ mass unreported',15);else art+=txt(477,168,'Thiol: '+thiol,16)+txt(477,197,'H₂: '+hydrogen,16)+txt(470,246,'Thiol loops: 100 / 200 µL',13)+txt(470,272,'H₂ loop: 800 µL',14);art+=txt(433,322,'Simultaneous thiol + H₂',17);return art+note('Two serial six-port valves. Loop capacities are apparatus volumes; they do not replace source masses or molar ratios.');}''')
fn('hold',r'''function hold(o,r){const inherited=/^shah-2001-(ir|pt)$/.test(r.record_id);return summary(o,cell(177,224,{fluid:true,particles:true,heat:true}))+note(inherited?'* The 3 h hold is inherited from the common methods; it is not an independently timed Ir/Pt experiment.':'The source uses a 3 h hold; darkest appearance at about 1 h is a separate visual observation, not quantitative completion.');}''')
fn('disperse',r'''function disperse(o){return heading(o.label)+vial(112,202,{solid:true})+arrow(214,178)+box(263,120,142,90)+txt(334,168,'Acetone',22)+arrow(423,211)+vial(505,213)+txt(310,315,'Redispersion for analysis',18)+note('Fluorinated solvents are reported alternatives, not simultaneous additions. Volumes and intermediate drying are unreported.');}''')
fn('microscopy',r'''function microscopy(o){const eds=o.id==='eds';return heading(o.label)+box(29,95,133,63)+txt(95,134,'Electron beam',16)+arrow(202,125)+box(254,96,54,99)+txt(282,222,'Grid specimen',15)+path('M281 230V263H175')+arrow(187,263,180)+box(29,234,143,64)+txt(100,261,eds?'Oxford Link ISIS':'JEOL 2010 TEM',14)+txt(100,285,eds?'EDS acquisition':'GATAN imaging',14)+conditions(o)+note(eds?'Printed Figure 6 is Ag-specific. No acquisition time, quantitative composition or synthetic EDS signal is invented.':'200 kV is electron acceleration; 1.7 Å is instrument point resolution, not a measured sample lattice spacing.');}''')
fn('measure',r'''function measure(o){return heading(o.label)+box(45,109,220,163)+txt(155,153,'Original TEM images',18)+txt(155,195,'Scion Image',20)+txt(155,238,quantity(o.parameters.minimum_particles_per_sample)+' / sample',16)+arrow(301,191)+box(348,111,209,163)+txt(452,155,'Measured diameters',17)+txt(452,204,'Keep A–I labels',17)+txt(452,245,'Mean and distribution',16)+note('Distribution width describes population polydispersity. It is not measurement uncertainty or a separate synthesis run.');}''')
fn('analysis',r'''function analysis(o){const labels={volume:[['Measured TEM diameters','Each source experiment','A–I remain separate'],['Assume spherical particles','Convert diameter to volume','No measured atomic shape']],normalize:[['Particle volume distribution','n(v), total count N∞','Total particle volume φ'],['ψ₁(η) = n(v)φ / N∞²','η = vN∞ / φ','Compare original Figure 9']],moments:[['Particle radius data','Arithmetic, cubic and','harmonic radius means'],['µ₁ = r₃ / rₕ','µ₃ = r₁ / r₃','Source classification criteria']],cumulative:[['Normalized A–I distributions','Cumulative count Nᵥ','Keep specimen labels'],['ψ₂(η) = Nᵥ / N∞','Compare Brownian model','Original Figure 10']]};const t=labels[o.id];return heading(o.label)+box(31,108,245,171)+t[0].map((v,i)=>txt(153,151+i*44,v,i===0?17:15)).join('')+arrow(307,193)+box(348,108,225,171)+t[1].map((v,i)=>txt(460,151+i*44,v,i===0?17:15)).join('')+note(o.id==='cumulative'?'The theory curve assumes unit sticking probability. The authors infer lower actual sticking; no fitted value is supplied.':o.id==='volume'?'Spherical conversion is an analytical assumption; no atomistic particle geometry or numerical volume dataset is reconstructed.':o.id==='moments'?'Reported ratios summarize the data; they are not new sample measurements or unqualified raw statistical moments.':'Source distribution definitions and original data remain separate from model curves; no synthetic histogram is generated.');}''')
old='const actions={load:loading,fill,pressurize,heat,inject,hold,cool,depressurize,vent,collect,precipitate,separate,redisperse:disperse,grid,microscopy,measure,analysis};'
new='const actions={load:loading,fill,condition:pressurize,inject,hold,cool,depressurize,vent,collect,precipitate,redisperse:disperse,deposit:grid,image:microscopy,size:measure,eds:microscopy,volume:analysis,normalize:analysis,moments:analysis,cumulative:analysis};'
assert s.count(old)==1;s=s.replace(old,new)
p.write_text(s,encoding='utf8')
